import React, { useState, useEffect } from "react";
import { Link, useNavigate } from "react-router-dom";
import axios from "axios";

import Headerreg from "../components/Header_reg";

const BASE_URL = "http://localhost:3001/ususarios/";
const Registro = () => {
  const [items, setItems] = useState([]);
  const [nombre, setNombre] = useState("");
  const [correo, setCorreo] = useState("");
  const [password, setPassword] = useState("");

  const navigate = useNavigate();

  useEffect(() => {
    axios.get(`${BASE_URL}`)
      .then((response) => {
        setItems(response.data);
        console.log(response.data);
      })
      .catch(error => {
        console.error("Error al obtener los usuarios:", error)
      });
  }, []);

  const handleCreate = () => {
    if (nombre.trim() && correo.trim() && password.trim()) {
      
      axios.post(`${BASE_URL}`, { 
        nombre: nombre,
        correo: correo,
        password: password
      })
      .catch(error => {
        console.error("Error al registrar el usuario:", error);
      });
    } 
  };

  return (
    <>
      <Headerreg />
      
      <main>
        <form className="form-registro" onSubmit={manejarRegistro}>
          <h2 className="subtitulo">Crear cuenta</h2>

          <label htmlFor="nombre">Nombre</label>
          <input
            type="text"
            value={nombre}
            onChange={(e) => setNombre(e.target.value)}
            placeholder="Ingrese tu nombre"
          />

          <label htmlFor="correo">Correo electrónico</label>
          <input
            type="email"
            value={correo}
            onChange={(e) => setCorreo(e.target.value)}
            placeholder="Ingrese tu correo"
          />

          <label htmlFor="password">Contraseña</label>
          <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            placeholder="Ingresa tu contraseña"
          />

          <button onClick={handleCreate}>Registrarse</button>
        </form>
      </main>
        </>
    );
}
